settings.custom_css:
selector .ak-nowrap .elementor-heading-title { white-space: nowrap; }
/* dorado de 3 tonos (solo color) */
selector .ak-oro-text .elementor-heading-title { background-image: linear-gradient(to bottom right, #CB861B 0%, #F5C02F 50%, #CB861B 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .ak-oro-box .elementor-icon { background-image: linear-gradient(to bottom right, #CB861B 0%, #F5C02F 50%, #CB861B 100%) !important; }
selector .ak-plan-dl .elementor-button { border-image: linear-gradient(to bottom right, #CB861B 0%, #F5C02F 50%, #CB861B 100%) 1 !important; }
@media (max-width: 1024px) { selector .ak-dk { display: none; } }
selector .ak-mb { display: none; }
@media (max-width: 767px) {
  selector .ak-mb { display: inline; }
  selector .ak-dk { display: none; }
  /* 3 datos en columnas iguales y centrados, como el XD móvil */
  selector .ak-stats-row { display: grid !important; grid-template-columns: repeat(3, 1fr); width: 100%; }
  selector .ak-stat { align-items: center !important; text-align: center; padding-left: 6px !important; padding-right: 6px !important; width: auto !important; }
  selector .ak-stat:first-child { padding-left: 0 !important; }
  selector .ak-stat .elementor-widget-icon .elementor-icon-wrapper, selector .ak-stat .elementor-heading-title { text-align: center; }
  selector .ak-nowrap .elementor-heading-title { white-space: normal; }
  selector .ak-plan-dl { align-self: center; }
}
selector .ak-stat { --width: auto; width: auto; flex: 0 0 auto; }
selector .ak-stats-row { --width: 100%; flex-wrap: nowrap; }
selector .ak-plan-left, selector .ak-plan-right { min-width: 0; }
selector .elementor-widget-text-editor p:last-child { margin-bottom: 0; }

selector { counter-reset: mod; border-top: 1px solid #CCD0D4; max-height: 720px; overflow-y: auto; padding-right: 14px;
  scrollbar-width: thin; scrollbar-color: #CB861B transparent; }
selector::-webkit-scrollbar { width: 4px; }
selector::-webkit-scrollbar-thumb { background: #CB861B; border-radius: 4px; }
selector .e-n-accordion-item > .e-con, selector .e-n-accordion-item > [role="region"] { border: 0 !important; background: none !important; --border-width: 0; margin: 0 !important; }
selector .e-n-accordion-item { counter-increment: mod; border-bottom: 1px solid #CCD0D4; padding: 0 !important; margin: 0 !important; }
selector .e-n-accordion-item-title { display: grid !important; grid-template-columns: 90px minmax(0, 1fr) auto; column-gap: 14px;
  align-items: start; padding: 40px 0 34px 10px !important; border: 0 !important; background: none !important; cursor: pointer; list-style: none; }
selector .e-n-accordion-item-title::-webkit-details-marker { display: none; }
selector .e-n-accordion-item-title::before { content: "Módulo"; grid-column: 1 / -1; grid-row: 1; margin-bottom: 10px;
  font: 400 16px/1 Inter, sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #CB861B; background-image: linear-gradient(to bottom right, #CB861B 0%, #F5C02F 50%, #CB861B 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .e-n-accordion-item-title::after { content: counter(mod, decimal-leading-zero); grid-column: 1; grid-row: 2;
  font: 500 56px/1 Montserrat, sans-serif; color: #CB861B; background-image: linear-gradient(to bottom right, #CB861B 0%, #F5C02F 50%, #CB861B 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .e-n-accordion-item-title-header { grid-column: 2; grid-row: 2; padding-top: 12px; max-width: 460px; }
selector .e-n-accordion-item-title-text { font: 600 24px/1.2 Barlow, sans-serif !important; color: #060606 !important; }
selector .e-n-accordion-item-title-icon { grid-column: 3; grid-row: 2; padding-top: 20px; display: flex !important; align-items: center; }
selector .e-n-accordion-item:not([open]) .e-n-accordion-item-title-icon .e-opened,
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon .e-closed { display: none !important; }
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon .e-opened,
selector .e-n-accordion-item:not([open]) .e-n-accordion-item-title-icon .e-closed { display: inline-flex !important; }
selector .e-n-accordion-item-title-icon > span { align-items: center; gap: 10px;
  font: 500 16px/1 Inter, sans-serif; letter-spacing: .14em; text-transform: uppercase; color: #808591; }
selector .e-n-accordion-item-title-icon .e-closed::before { content: "Ver contenido"; }
selector .e-n-accordion-item-title-icon .e-opened::before { content: "Ocultar"; }
selector .e-n-accordion-item-title-icon i, selector .e-n-accordion-item-title-icon svg { width: 20px; font-size: 20px; color: #808591; fill: #808591; }
@media (max-width: 1366px) {
  selector { max-height: 560px; }
  selector .e-n-accordion-item-title { padding: 30px 0 26px 10px !important; }
  selector .e-n-accordion-item-title { grid-template-columns: 72px minmax(0, 1fr) auto; column-gap: 12px; }
  selector .e-n-accordion-item-title::before { font-size: 13px; }
  selector .e-n-accordion-item-title::after { font-size: 46px; }
  selector .e-n-accordion-item-title-header { padding-top: 9px; max-width: 380px; }
  selector .e-n-accordion-item-title-text { font-size: 20px !important; }
  selector .e-n-accordion-item-title-icon { padding-top: 16px; }
  selector .e-n-accordion-item-title-icon > span { font-size: 12px; }
}
@media (max-width: 767px) {
  selector { max-height: none; overflow: visible; padding-right: 0; }
  selector .e-n-accordion-item-title { padding: 24px 0 22px 0 !important; }
  selector .e-n-accordion-item-title { grid-template-columns: 52px minmax(0, 1fr) auto; column-gap: 10px; }
  selector .e-n-accordion-item-title::before { font-size: 10px; }
  selector .e-n-accordion-item-title::after { font-size: 26px; }
  selector .e-n-accordion-item-title-header { padding-top: 4px; max-width: none; }
  selector .e-n-accordion-item-title-text { font-size: 13px !important; }
  selector .e-n-accordion-item-title-icon { padding-top: 6px; }
  selector .e-n-accordion-item-title-icon span::before { content: none !important; }
}
